nextflow_process {

    name "Test Process MITORSAW_HAPLOTYPE"
    script "../main.nf"
    process "MITORSAW_HAPLOTYPE"

    tag "modules"
    tag "modules_nfcore"
    tag "mitorsaw"
    tag "mitorsaw/haplotype"

    test("homo_sapiens - bam") {

        when {
            process {
                """
                input[0] = [
                    [ id:'sample_1' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/200080.GRCh38.haplotagged.chrM.downsampled.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/200080.GRCh38.haplotagged.chrM.downsampled.bam.bai', checkIfExists: true),
                ]
                input[1] = [
                    [ id:'sample_1'],
                    file('https://raw.githubusercontent.com/nf-core/test-datasets/refs/heads/raredisease/reference/Homo_sapiens_assembly38_chr20_chrM.fasta', checkIfExists: true),
                    file('https://raw.githubusercontent.com/nf-core/test-datasets/refs/heads/raredisease/reference/Homo_sapiens_assembly38_chr20_chrM.fasta.fai', checkIfExists: true),
                ]
                input[2] = false
                input[3] = false
                """
            }
        }

        then {

            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

